package com.sigtm.backend.service;
import com.sigtm.backend.exception.ResourceNotFoundException; import com.sigtm.backend.model.*; import com.sigtm.backend.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class ContratoProveedorService {private final ContratoProveedorRepository contracts;private final ProveedorRepository suppliers;private final AuditoriaService audit;
 @Transactional public ContratoProveedor crear(Long supplierId,ContratoProveedor data){Proveedor s=suppliers.findById(supplierId).orElseThrow(()->new ResourceNotFoundException("Proveedor no encontrado"));if(data.getEndsAt().isBefore(data.getStartsAt()))throw new IllegalArgumentException("La vigencia del contrato no es válida");data.setSupplier(s);data.setCode("CP-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());if(data.getActive()==null)data.setActive(true);ContratoProveedor saved=contracts.save(data);audit.registrar("CREATE","CONTRATO_PROVEEDOR",saved.getId(),"Contrato "+saved.getCode());return saved;}
 @Transactional(readOnly=true) public List<ContratoProveedor> listar(Long supplierId){return contracts.findBySupplierIdOrderByStartsAtDesc(supplierId);}
 @Transactional public ContratoProveedor desactivar(Long id){ContratoProveedor c=contracts.findById(id).orElseThrow(()->new ResourceNotFoundException("Contrato no encontrado"));c.setActive(false);audit.registrar("UPDATE","CONTRATO_PROVEEDOR",id,"Contrato desactivado");return contracts.save(c);}}
